"use client";

//! Browser-safe entry: renders SVG that was produced ahead of time (`./codegen`, the
//! `m3:icon/` plugin or a server call to `m3Icon`). Nothing here reaches `@aphrody/bun`.

export interface M3IconSvgProps {
  /** Complete `<svg>` markup generated by `m3Icon`, `./codegen` or the `m3:icon/` plugin. */
  svg: string;
  /** Accessible name; renders `role="img"` with `aria-label` when set, `aria-hidden` otherwise. */
  title?: string;
  className?: string;
}

/** Renders pre-generated Material Symbols SVG inline, with no native binding in the client bundle. */
export function M3IconSvg({ svg, title, className }: M3IconSvgProps) {
  return (
    <span
      className={className}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      // biome-ignore lint: the SVG string comes from the build-time generator, not user input.
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
